package com.inventra.backend.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDateTime; import java.util.*;
@Document(collection="purchase_orders") public class PurchaseOrder { @Id private String id; private String poNumber; private String warehouseId; private String supplierName; private List<PurchaseOrderItem> items=new ArrayList<>(); private PurchaseOrderStatus status=PurchaseOrderStatus.DRAFT; private LocalDateTime createdAt=LocalDateTime.now(); private LocalDateTime updatedAt=LocalDateTime.now(); public PurchaseOrder(){} public String getId(){return id;} public void setId(String v){id=v;} public String getPoNumber(){return poNumber;} public void setPoNumber(String v){poNumber=v;} public String getWarehouseId(){return warehouseId;} public void setWarehouseId(String v){warehouseId=v;} public String getSupplierName(){return supplierName;} public void setSupplierName(String v){supplierName=v;} public List<PurchaseOrderItem> getItems(){return items;} public void setItems(List<PurchaseOrderItem> v){items=v;} public PurchaseOrderStatus getStatus(){return status;} public void setStatus(PurchaseOrderStatus v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
